window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e8ca11d5618fee0d"]={"versions": [{"id": "FIG-e8ca11d5618fee0d", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von VFB-Timing-Ereignissen bezüglich Operationen im Kontext der AUTOSAR Timing Extensions (Adaptive Platform). Das Diagramm modelliert die strukturellen Metaklassen zur zeitlichen Erfassung und Beschreibung von Funktionsaufrufen (Client-Server-Kommunikation) an Komponenten-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TDEventVfb</code>: Abstrakte Basisklasse, spezialisiert von <code>TimingDescriptionEvent</code>.\n</li><li><code>TDEventVfbPort</code>: Abstrakte Spezialisierung von <code>TDEventVfb</code>, besitzt das Attribut <code>+ isExternal: Boolean</code> und referenziert über die gerichtete Assoziation <code>+port</code> mit Kardinalität <code>0..1</code> die Klasse <code>PortPrototype</code> (stereotypisiert mit <code>AtpBlueprintable</code>, <code>AtpPrototype</code>).\n</li><li><code>TDEventOperation</code>: Spezialisierung von <code>TDEventVfbPort</code>, enthält das Attribut <code>+ tdEventOperationType: TDEventOperationTypeEnum</code> (obligatorisch, Kardinalität 1). Referenziert über die gerichtete Assoziation <code>+operation</code> mit Kardinalität <code>1</code> das Ziel <code>ClientServerOperation</code>.\n</li><li><code>ClientServerOperation</code>: Spezialisiert von <code>AtpStructureElement</code> und <code>Identifiable</code>, besitzt das optionale Attribut <code>+ fireAndForget: Boolean [0..1]</code>.\n</li><li><code>TDEventOperationTypeEnum</code>: Enumeration mit den Literalen <code>operationCalled</code>, <code>operationCallReceived</code>, <code>operationCallResponseSent</code> und <code>operationCallResponseReceived</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur ohne dynamische Ablaufsequenz. Die Enumeration <code>TDEventOperationTypeEnum</code> repräsentiert distinkte Zeitpunkte im Lebenszyklus eines Client-Server-Aufrufs:</p>\n<ol class=\"fig-list\"><li><code>operationCalled</code>: Initiierung des Aufrufs auf Client-Seite.\n</li><li><code>operationCallReceived</code>: Eintreffen der Operationsanfrage auf Server-Seite.\n</li><li><code>operationCallResponseSent</code>: Absenden der Operationsantwort durch den Server.\n</li><li><code>operationCallResponseReceived</code>: Eingang der Antwort beim aufrufenden Client.\n</li></ol>\n<p class=\"fig-p\">Das Attribut <code>fireAndForget</code> an <code>ClientServerOperation</code> bestimmt, ob ein Antwortzyklus entfällt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Instanzen von <code>TDEventOperation</code> ist die Zuordnung einer konkreten <code>ClientServerOperation</code> über <code>+operation</code> mit Kardinalität <code>1</code> sowie die Angabe des Ereignistyps über <code>tdEventOperationType</code> zwingend erforderlich. Die Port-Referenz <code>+port</code> ist mit <code>0..1</code> optional. <code>isExternal</code> kennzeichnet explizit, ob die Port-Interaktion komponentenextern erfolgt. Modellelemente müssen konsistent zu den übergeordneten Identifiable- und VFB-Strukturen instanziiert werden.</p>"}, {"id": "FIG-287d53722be47d17", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von VFB-Timing-Ereignissen bezüglich Operationen im Kontext der AUTOSAR Timing Extensions (Adaptive Platform). Das Diagramm modelliert die strukturellen Metaklassen zur zeitlichen Erfassung und Beschreibung von Funktionsaufrufen (Client-Server-Kommunikation) an Komponenten-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TDEventVfb</code>: Abstrakte Basisklasse, spezialisiert von <code>TimingDescriptionEvent</code>.\n</li><li><code>TDEventVfbPort</code>: Abstrakte Spezialisierung von <code>TDEventVfb</code>, besitzt das Attribut <code>+ isExternal: Boolean</code> und referenziert über die gerichtete Assoziation <code>+port</code> mit Kardinalität <code>0..1</code> die Klasse <code>PortPrototype</code> (stereotypisiert mit <code>AtpBlueprintable</code>, <code>AtpPrototype</code>).\n</li><li><code>TDEventOperation</code>: Spezialisierung von <code>TDEventVfbPort</code>, enthält das Attribut <code>+ tdEventOperationType: TDEventOperationTypeEnum</code> (obligatorisch, Kardinalität 1). Referenziert über die gerichtete Assoziation <code>+operation</code> mit Kardinalität <code>1</code> das Ziel <code>ClientServerOperation</code>.\n</li><li><code>ClientServerOperation</code>: Spezialisiert von <code>AtpStructureElement</code> und <code>Identifiable</code>, besitzt das optionale Attribut <code>+ fireAndForget: Boolean [0..1]</code>.\n</li><li><code>TDEventOperationTypeEnum</code>: Enumeration mit den Literalen <code>operationCalled</code>, <code>operationCallReceived</code>, <code>operationCallResponseSent</code> und <code>operationCallResponseReceived</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur ohne dynamische Ablaufsequenz. Die Enumeration <code>TDEventOperationTypeEnum</code> repräsentiert distinkte Zeitpunkte im Lebenszyklus eines Client-Server-Aufrufs:</p>\n<ol class=\"fig-list\"><li><code>operationCalled</code>: Initiierung des Aufrufs auf Client-Seite.\n</li><li><code>operationCallReceived</code>: Eintreffen der Operationsanfrage auf Server-Seite.\n</li><li><code>operationCallResponseSent</code>: Absenden der Operationsantwort durch den Server.\n</li><li><code>operationCallResponseReceived</code>: Eingang der Antwort beim aufrufenden Client.\n</li></ol>\n<p class=\"fig-p\">Das Attribut <code>fireAndForget</code> an <code>ClientServerOperation</code> bestimmt, ob ein Antwortzyklus entfällt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Instanzen von <code>TDEventOperation</code> ist die Zuordnung einer konkreten <code>ClientServerOperation</code> über <code>+operation</code> mit Kardinalität <code>1</code> sowie die Angabe des Ereignistyps über <code>tdEventOperationType</code> zwingend erforderlich. Die Port-Referenz <code>+port</code> ist mit <code>0..1</code> optional. <code>isExternal</code> kennzeichnet explizit, ob die Port-Interaktion komponentenextern erfolgt. Modellelemente müssen konsistent zu den übergeordneten Identifiable- und VFB-Strukturen instanziiert werden.</p>"}, {"id": "FIG-e62e746e232a9a3d", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von VFB-Timing-Ereignissen bezüglich Operationen im Kontext der AUTOSAR Timing Extensions (Adaptive Platform). Das Diagramm modelliert die strukturellen Metaklassen zur zeitlichen Erfassung und Beschreibung von Funktionsaufrufen (Client-Server-Kommunikation) an Komponenten-Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>TDEventVfb</code>: Abstrakte Basisklasse, spezialisiert von <code>TimingDescriptionEvent</code>.\n</li><li><code>TDEventVfbPort</code>: Abstrakte Spezialisierung von <code>TDEventVfb</code> ohne eigene Attribute. Referenziert über die gerichtete Assoziation <code>+port</code> mit Kardinalität <code>0..1</code> die Klasse <code>PortPrototype</code> (stereotypisiert mit <code>AtpBlueprintable</code>, <code>AtpPrototype</code>).\n</li><li><code>TDEventOperation</code>: Spezialisierung von <code>TDEventVfbPort</code>, enthält das optionale Attribut <code>+ tdEventOperationType: TDEventOperationTypeEnum [0..1]</code>. Referenziert über die gerichtete Assoziation <code>+operation</code> mit Kardinalität <code>0..1</code> das Ziel <code>ClientServerOperation</code>.\n</li><li><code>ClientServerOperation</code>: Spezialisiert von <code>AtpStructureElement</code> und <code>Identifiable</code>, besitzt das optionale Attribut <code>+ fireAndForget: Boolean [0..1]</code>.\n</li><li><code>TDEventOperationTypeEnum</code>: Enumeration mit den Literalen <code>operationCalled</code>, <code>operationCallReceived</code>, <code>operationCallResponseSent</code> und <code>operationCallResponseReceived</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur ohne dynamische Ablaufsequenz. Die Enumeration <code>TDEventOperationTypeEnum</code> repräsentiert distinkte Zeitpunkte im Lebenszyklus eines Client-Server-Aufrufs:</p>\n<ol class=\"fig-list\"><li><code>operationCalled</code>: Initiierung des Aufrufs auf Client-Seite.\n</li><li><code>operationCallReceived</code>: Eintreffen der Operationsanfrage auf Server-Seite.\n</li><li><code>operationCallResponseSent</code>: Absenden der Operationsantwort durch den Server.\n</li><li><code>operationCallResponseReceived</code>: Eingang der Antwort beim aufrufenden Client.\n</li></ol>\n<p class=\"fig-p\">Das Attribut <code>fireAndForget</code> an <code>ClientServerOperation</code> bestimmt, ob ein Antwortzyklus entfällt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">In <code>TDEventOperation</code> sind sowohl die Referenz <code>+operation</code> auf eine <code>ClientServerOperation</code> als auch das Attribut <code>tdEventOperationType</code> optional mit Kardinalität <code>[0..1]</code> spezifiziert, was unvollständig gebundene oder generische Timing-Ereignisse ermöglicht. Die Klasse <code>TDEventVfbPort</code> besitzt kein Attribut <code>isExternal</code> mehr. Die Port-Zuordnung über <code>+port</code> verbleibt optional (<code>0..1</code>).</p>"}], "trans": [{"from": "FIG-e8ca11d5618fee0d", "to": "FIG-287d53722be47d17", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-287d53722be47d17", "to": "FIG-e62e746e232a9a3d", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>TDEventVfbPort</code>: Attribut <code>isExternal: Boolean</code> entfernt.\n</li><li><code>TDEventOperation</code>: Multiplizität des Attributs <code>tdEventOperationType</code> von <code>1</code> (implizit) auf <code>[0..1]</code> geändert.\n</li><li><code>TDEventOperation</code> -&gt; <code>ClientServerOperation</code>: Multiplizität der Assoziationsrolle <code>+operation</code> von <code>1</code> auf <code>0..1</code> gelockert.\n</li></ul>"}]};
